const sheet = context.workbook.worksheets.getItem("2047");
const used = sheet.getUsedRangeOrNullObject();
used.load("address,rowCount,columnCount");
await context.sync();
// search row 4/5 header for "Total"
const headerRange = sheet.getRange("A4:DQ5");
headerRange.load("values");
await context.sync();
const row4 = headerRange.values[0];
const row5 = headerRange.values[1];
let totalCols = [];
for (let i=0;i<row4.length;i++) {
  if ((row4[i] && String(row4[i]).toLowerCase().includes("total")) || (row5[i] && String(row5[i]).toLowerCase().includes("total"))) {
    totalCols.push({col:i, colLetter: String.fromCharCode(65+ (i%26)), row4:row4[i], row5:row5[i]});
  }
}
return { used: used.address, totalCols };

