const tyi = context.workbook.worksheets.getItem("Target Year Input");
const main = context.workbook.worksheets.getItem("IESS V3 Main Sheet");
const sheet2047 = context.workbook.worksheets.getItem("2047");

const choiceCell = tyi.getRange("E10");
const scenarioCell = main.getRange("E12");
const t22 = sheet2047.getRange("T22");

// save originals
choiceCell.load("values");
scenarioCell.load("values");
await context.sync();
const origChoice = choiceCell.values[0][0];
const origScenario = scenarioCell.values[0][0];

const results = {};

// Test input.choice = 1 with various predefined scenarios
choiceCell.values = [[1]];
await context.sync();

for (const scen of [1,2,3,4]) {
  scenarioCell.values = [[scen]];
  await context.sync();
  context.workbook.application.calculate(Excel.CalculationType.full);
  await context.sync();
  t22.load("values");
  await context.sync();
  results["choice1_scenario"+scen] = t22.values[0][0];
}

// restore originals
choiceCell.values = [[origChoice]];
scenarioCell.values = [[origScenario]];
await context.sync();
context.workbook.application.calculate(Excel.CalculationType.full);
await context.sync();
t22.load("values");
await context.sync();
results["restored_T22"] = t22.values[0][0];

return { origChoice, origScenario, results };

