const main = context.workbook.worksheets.getItem("IESS V3 Main Sheet");
const io = context.workbook.worksheets.getItem("Intermediate output");
const scenarioCell = main.getRange("E12");

const cells = io.getRange("BF29:BF54");
cells.load("values");
await context.sync();

const results = {};
for (const scen of [1,2,3,4]) {
  scenarioCell.values = [[scen]];
  await context.sync();
  context.workbook.application.calculate(Excel.CalculationType.full);
  await context.sync();
  const r = io.getRange("BF29:BF54");
  r.load("values");
  await context.sync();
  const v = r.values;
  // indices: row29 is v[0], so BF29+i corresponds to v[i]. BF29=idx0,...BF54=idx25
  results["scenario"+scen] = {
    Nuclear: v[29-29][0],
    Solar: v[30-29][0],
    Wind: v[31-29][0],
    Hydro: v[35-29][0],
    ElecImport: v[36-29][0],
    Coal: v[47-29][0],
    Oil: v[50-29][0],
    Gas: v[53-29][0],
    Total: v[54-29][0]
  };
}
return results;

