const sheetNames = ["IESS V3 Results","IESS V3 Main Sheet","Intermediate output","My Story"];
let foundResults = [];
for (const name of sheetNames) {
  const sheet = context.workbook.worksheets.getItem(name);
  const used = sheet.getUsedRangeOrNullObject();
  used.load("isNullObject");
  await context.sync();
  if (used.isNullObject) continue;
  const found = sheet.getRange("A1").worksheet.getUsedRange().findOrNullObject("Import Depend", {completeMatch:false, matchCase:false});
  found.load("address,isNullObject");
  await context.sync();
  if (!found.isNullObject) foundResults.push({sheet:name, addr: found.address});
}
return foundResults;

